export interface Submission {
  id: string;
  bytes: number;
  kind: string;
}

export type GateDecision =
  | { ok: true; accepted: Submission[]; entries: Submission[] }
  | { ok: false; reason: 'duplicate-id' | 'item-count' | 'total-bytes' | 'kind' };

export class SubmissionGate {
  private readonly allowed: Set<string>;

  public constructor(
    private readonly maxTotalBytes: number,
    private readonly maxItems: number,
    allowedKinds: readonly string[] = [],
  ) {
    SubmissionGate.validateLimit(maxTotalBytes);
    SubmissionGate.validateLimit(maxItems);
    if (!Array.isArray(allowedKinds) || allowedKinds.some(
      (kind: string) => typeof kind !== 'string' || kind.trim().length === 0,
    )) {
      throw new TypeError('Allowed kinds must be non-empty strings');
    }
    this.allowed = new Set(allowedKinds);
  }

  public assess(entries: readonly Submission[]): GateDecision {
    if (!Array.isArray(entries)) throw new TypeError('Entries must be an array');

    for (const entry of entries) {
      if (
        entry === null ||
        typeof entry !== 'object' ||
        typeof entry.id !== 'string' ||
        entry.id.trim().length === 0 ||
        typeof entry.kind !== 'string' ||
        entry.kind.trim().length === 0 ||
        typeof entry.bytes !== 'number' ||
        !Number.isSafeInteger(entry.bytes) ||
        entry.bytes < 0
      ) {
        throw new TypeError('Malformed submission');
      }
    }

    const ids = new Set<string>();
    for (const entry of entries) {
      if (ids.has(entry.id)) return { ok: false, reason: 'duplicate-id' };
      ids.add(entry.id);
    }

    if (entries.length > this.maxItems) return { ok: false, reason: 'item-count' };

    let total = 0;
    for (const entry of entries) {
      if (total > Number.MAX_SAFE_INTEGER - entry.bytes) {
        return { ok: false, reason: 'total-bytes' };
      }
      total += entry.bytes;
    }
    if (total >= this.maxTotalBytes) return { ok: false, reason: 'total-bytes' };

    if (this.allowed.size > 0 && entries.some((entry: Submission) => !this.allowed.has(entry.kind))) {
      return { ok: false, reason: 'kind' };
    }

    const accepted = entries.map((entry: Submission) => ({
      id: entry.id,
      bytes: entry.bytes,
      kind: entry.kind,
    }));
    return { ok: true, accepted, entries: accepted };
  }

  private static validateLimit(value: number): void {
    if (typeof value !== 'number') throw new TypeError('Limits must be numbers');
    if (!Number.isSafeInteger(value) || value < 0) {
      throw new RangeError('Limits must be non-negative safe integers');
    }
  }
}

