import { SubmissionGate } from './solution';
import type { Submission } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throws(action: () => void, ctor: Function, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof (ctor as new (...args: never[]) => Error), message);
}

throws(() => new SubmissionGate(-1, 1), RangeError, 'negative byte limit');
throws(() => new SubmissionGate(1.5, 1), RangeError, 'fractional byte limit');
throws(() => new SubmissionGate(Number.MAX_SAFE_INTEGER + 1, 1), RangeError, 'unsafe byte limit');
throws(() => new SubmissionGate(1, -1), RangeError, 'negative item limit');
throws(() => new SubmissionGate('1' as unknown as number, 1), TypeError, 'non-number limit');
throws(() => new SubmissionGate(1, 1, ['ok', '  ']), TypeError, 'blank allowed kind');

const unrestricted = new SubmissionGate(0, 0, []);
const empty = unrestricted.assess([]) as { ok: boolean; entries?: Submission[] };
equal(empty.ok, true, 'empty batch is valid at zero limits');
assert(Array.isArray(empty.entries), 'successful decision contains entries');
equal(empty.entries.length, 0, 'successful empty entries');

const input: Submission[] = [
  { id: 'a', bytes: 2, kind: 'image' },
  { id: 'b', bytes: 3, kind: 'image' },
];
const gate = new SubmissionGate(5, 2, ['image']);
const success = gate.assess(input) as { ok: boolean; entries: Submission[] };
equal(success.ok, true, 'inclusive limits succeed');
equal(success.entries.length, 2, 'successful count');
equal(success.entries[0].id, 'a', 'order preserved');
equal(success.entries[1].bytes, 3, 'fields preserved');
assert(success.entries !== input, 'result array must be copied');
assert(success.entries[0] !== input[0], 'result objects must be copied');
input[0].kind = 'changed';
equal(success.entries[0].kind, 'image', 'input mutation must not affect output');
success.entries[1].bytes = 99;
equal(input[1].bytes, 3, 'output mutation must not affect input');

const duplicate = gate.assess([
  { id: 'same', bytes: 4, kind: 'bad' },
  { id: 'same', bytes: 4, kind: 'bad' },
]);
equal(duplicate.ok, false, 'duplicate decision');
if (!duplicate.ok) equal(duplicate.reason, 'duplicate-id', 'duplicate priority');

const count = gate.assess([
  { id: '1', bytes: 4, kind: 'bad' },
  { id: '2', bytes: 4, kind: 'bad' },
  { id: '3', bytes: 4, kind: 'bad' },
]);
equal(count.ok, false, 'count decision');
if (!count.ok) equal(count.reason, 'item-count', 'item count priority');

const bytes = gate.assess([
  { id: '1', bytes: 3, kind: 'bad' },
  { id: '2', bytes: 3, kind: 'bad' },
]);
if (!bytes.ok) equal(bytes.reason, 'total-bytes', 'total byte priority');
else throw new Error('byte overflow must fail');

const kind = gate.assess([{ id: '1', bytes: 1, kind: 'video' }]);
if (!kind.ok) equal(kind.reason, 'kind', 'disallowed kind');
else throw new Error('disallowed kind must fail');

throws(() => gate.assess([{ id: ' ', bytes: 0, kind: 'image' }]), TypeError, 'blank id');
throws(() => gate.assess([{ id: 'x', bytes: -1, kind: 'image' }]), TypeError, 'negative bytes');
throws(() => gate.assess([{ id: 'x', bytes: 1.2, kind: 'image' }]), TypeError, 'fractional bytes');
throws(() => gate.assess([{ id: 'x', bytes: 0, kind: '' }]), TypeError, 'blank kind');
throws(() => gate.assess(null as unknown as readonly Submission[]), TypeError, 'entries must be an array');

